    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def as_pos(v):
        if isinstance(v, dict):
            x = v.get("x", v.get("col", v.get("cx", v.get("row", None))))
            y = v.get("y", v.get("row", v.get("cy", v.get("col", None))))
            if x is not None and y is not None:
                return [x, y]
        elif isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def get_first_pos(obj, keys):
        if not isinstance(obj, dict):
            return None
        for k in keys:
            if k in obj:
                p = as_pos(obj.get(k))
                if p is not None:
                    return p
        return None

    def extract_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            p = as_pos(value)
            if p is not None:
                out.append(p)
            else:
                for vv in value.values():
                    out.extend(extract_positions(vv))
        elif isinstance(value, (list, tuple)):
            if len(value) >= 2 and not isinstance(value[0], (list, tuple, dict)):
                p = as_pos(value)
                if p is not None:
                    out.append(p)
            else:
                for item in value:
                    out.extend(extract_positions(item))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(z):
        return 0 if z == 0 else (1 if z > 0 else -1)

    if not isinstance(observation, dict):
        return [0, 0]

    me = get_first_pos(observation, ["position", "pos", "agent", "self", "me", "player", "location", "loc"])
    if me is None:
        me = get_first_pos(observation.get("agent_state", {}), ["position", "pos", "location", "loc"])
    if me is None:
        return [0, 0]

    resources = []
    for k in ["resources", "resource", "food", "items", "targets", "goals", "objective", "objectives"]:
        resources.extend(extract_positions(observation.get(k)))

    enemies = []
    for k in ["enemies", "enemy", "opponents", "opponent", "others", "pursuers", "predators", "agents"]:
        enemies.extend(extract_positions(observation.get(k)))

    bases = []
    for k in ["bases", "base", "home", "homes", "spawn", "spawns", "territory_targets", "frontier"]:
        bases.extend(extract_positions(observation.get(k)))

    allies = []
