            nearest_base = b

    for dx, dy in candidates:
        nx = me[0] + dx
        ny = me[1] + dy
        score = 0

        # Prefer staying put only if all else is bad
        if dx == 0 and dy == 0:
            score -= 0.2

        # Threat avoidance / pursuit-evasion
        if nearest_enemy is not None:
            d_now = nearest_enemy_dist
            d_new = manhattan([nx, ny], nearest_enemy)
            if d_new > d_now:
