            if d_now is not None and d_now <= 3:
                score += (d_new - d_now) * 4.0

        # Resource collection
        if nearest_resource is not None:
            d_now = nearest_resource_dist
            d_new = manhattan([nx, ny], nearest_resource)
            score += (d_now - d_new) * 2.5

        # Territory control / return-to-base patterns
        if nearest_base is not None:
